Q: Why can&#39;t I assign an std::optional of std::lock_guard? A: <p>You could call a function that optionally returns a guard, e.g.</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;mutex&gt;
#include &lt;optional&gt;

namespace {

bool useLock = false;
std::mutex m;

static std::optional&lt;std::lock_guard&lt;std::mutex&gt;&gt;
maybeLock()
{
  if (useLock) {
    return std::optional&lt;std::lock_guard&lt;std::mutex&gt;&gt;(m);
  }
  return std::nullopt;
}

}

int main() {
    {
        // no lock example
        useLock = false;
        auto guard = maybeLock();
        // ... do something
    }
    {
        // lock example
        useLock = true;
        auto guard = maybeLock();
        // ... do something
    }
}
</code></pre>
